export const metadata:Metadata={title:'Cookie Policy',description:'Information about cookies and technical tools used by the Marghera Venice Apartments website.',alternates:{canonical:'/en/cookie-policy',languages:{'it-IT': '/cookie-policy', 'en-GB': '/en/cookie-policy', 'de-DE': '/de/cookie-policy', 'fr-FR': '/fr/cookie-policy', 'es-ES': '/es/cookie-policy', 'zh-CN': '/zh/cookie-policy', 'x-default': '/cookie-policy'}},openGraph:{title:'Cookie Policy',description:'Information about cookies and technical tools used by the Marghera Venice Apartments website.',url:'/en/cookie-policy',locale:'en_GB',type:'website',images:['/images/home-rialto-vincenzo-landino.webp']},twitter:{card:'summary_large_image',title:'Cookie Policy',description:'Information about cookies and technical tools used by the Marghera Venice Apartments website.',images:['/images/home-rialto-vincenzo-landino.webp']}};
const sections=[{'title': 'Google Analytics 4', 'text': 'The website uses Google Analytics 4 (GA4) only after the user has given consent. Before acceptance, the Analytics tag is not loaded and analytics_storage remains set to denied. Google advertising storage and personalisation signals remain disabled (ad_storage, ad_user_data and ad_personalization set to denied).'}, {'title': 'Analytics cookies', 'text': 'After consent, Google Analytics may use cookies such as _ga and _ga_<id> to distinguish visits and produce aggregate statistics about website usage. You can refuse consent without losing access to the website.'}, {'title': 'Measured events', 'text': 'When Analytics is enabled, we may measure page views and useful interactions such as clicks on WhatsApp and email links. These events help us understand which content and channels are most useful to visitors and are not used on this website for advertising profiling.'}, {'title': 'Preferences and withdrawal', 'text': 'Your choice is stored locally in your browser so the website can remember it. You can reopen Cookie settings from the footer at any time and change your choice. If you refuse, Google Analytics remains disabled.'}, {'title': 'Technical functions and external links', 'text': 'The hosting/CDN provider and security systems may use technologies strictly necessary to deliver and protect the service. WhatsApp, WeChat, Instagram, Facebook and other external sites open only when you choose their links and are governed by their own privacy notices.'}, {'title': 'Updates', 'text': 'Last updated: 21 August 2026.'}];
